describe('Submit Button Disabled Until All Required Fields Filled', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should disable submit button until all required fields are filled', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/form-submit').as('submitForm');

    // Verify submit button is disabled initially
    cy.get('[data-testid="submit-button"]').should('be.disabled');

    // Fill in the first required field
    cy.get('[data-testid="first-name-input"]').type('John');

    // Verify submit button is still disabled
    cy.get('[data-testid="submit-button"]').should('be.disabled');

    // Fill in the second required field
    cy.get('[data-testid="last-name-input"]').type('Doe');

    // Verify submit button is still disabled
    cy.get('[data-testid="submit-button"]').should('be.disabled');

    // Fill in the third required field
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');

    // Verify submit button is now enabled
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');

    // Click the submit button
    cy.get('[data-testid="submit-button"]').click();

    // Verify form submission API was called
    cy.wait('@submitForm').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
  });

  it('should re-enable submit button when all required fields are cleared', () => {
    // Fill in all required fields
    cy.get('[data-testid="first-name-input"]').type('Jane');
    cy.get('[data-testid="last-name-input"]').type('Smith');
    cy.get('[data-testid="email-input"]').type('jane.smith@example.com');

    // Verify submit button is enabled
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');

    // Clear all fields
    cy.get('[data-testid="first-name-input"]').clear();
    cy.get('[data-testid="last-name-input"]').clear();
    cy.get('[data-testid="email-input"]').clear();

    // Verify submit button is now disabled
    cy.get('[data-testid="submit-button"]').should('be.disabled');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please fill all required fields');
  });
});
